\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{graphicx}
\usepackage{booktabs}

\title{Mapping Urban Green Space with Sentinel-2 Time Series}
\author{F.~Osei, I.~Novak, and H.~Tanabe}
\date{June 2026}

\begin{document}
\maketitle

\begin{abstract}
Urban green space is a critical determinant of heat exposure, stormwater
retention, and public health, yet municipal inventories are often
outdated or inconsistent across districts. We present an automated
mapping pipeline that combines monthly Sentinel-2 composites with a
gradient-boosted classifier trained on municipal reference polygons, and
we apply it to a mid-sized European city over six years. The pipeline
reproduces the municipal inventory with an overall accuracy of 93.1\%
and reveals a net gain of 4.7\% in green cover between 2019 and 2024,
concentrated in former industrial districts.
\end{abstract}

\section{Introduction}
The case for mapping urban vegetation is usually made in terms of
ecosystem services, but the more immediate motivation for many cities is
governance: tree-protection ordinances, green-roof subsidies, and
stormwater fees all require an inventory that is current, spatially
consistent, and defensible in disputes. Field-based inventories deliver
accuracy at prohibitive cost, and aerial photo interpretation, while
cheaper, introduces operator-dependent inconsistencies that make
year-to-year change estimates unreliable.

Medium-resolution satellite time series offer a way out of this
trade-off. Sentinel-2 provides 10~m imagery every five days, and
monthly composites suppress cloud contamination to the point where
phenological features can be computed for every pixel. The mapping
problem then reduces to a classification problem in which the temporal
profile of each pixel carries much of the signal: lawns, trees,
allotments, and water each have characteristic seasonal signatures.

\section{Study Area and Data}
The study area is a mid-sized European city of 420{,}000 inhabitants
with a compact historic core, ringed by industrial districts that have
been redeveloped over the past two decades. Figure~\ref{fig:study-area}
summarises the setting.
\begin{figure}[t]
\centering
\IfFileExists{figures/study_area.pdf}{\includegraphics[width=0.8\columnwidth]{figures/study_area.pdf}}{\rule{0.8\columnwidth}{3.6cm}}
\caption{Overview.}
\label{fig:study-area}
\end{figure}

The input data consist of all Sentinel-2 Level-2A scenes over the study
area from 2019 to 2024, composited monthly using the greenest pixel of
each period. Table~\ref{tab:sensors} lists the data sources.
\begin{table}[t]
\centering
\caption{Sensors.}
\label{tab:sensors}
\begin{tabular}{lll}
\toprule
Source & Resolution & Role \\
\midrule
Sentinel-2 & 10~m & spectral time series \\
Sentinel-1 & 10~m & texture features \\
LiDAR (2018) & 1~m & height reference \\
\bottomrule
\end{tabular}
\end{table}

The reference data are the municipal green-space polygons, which cover
parks, allotments, cemeteries, and street trees, together with a
stratified random sample of 1{,}200 validation points interpreted from
30~cm aerial imagery by two independent operators.

\section{Methods}
The classifier is a gradient-boosted ensemble trained on 48 features per
pixel: the monthly medians of four spectral bands and two vegetation
indices, their annual amplitudes, and texture measures from the radar
backscatter. Figure~\ref{fig:ndvi-series} motivates the feature design.
\begin{figure}[t]
\centering
\IfFileExists{figures/ndvi_series.pdf}{\includegraphics[width=0.85\columnwidth]{figures/ndvi_series.pdf}}{\rule{0.85\columnwidth}{3.4cm}}
\caption{Data.}
\label{fig:ndvi-series}
\end{figure}

Training polygons were filtered to remove boundary pixels and areas
smaller than five pixels, leaving 9{,}400 reference pixels across the
four target classes. The model was trained separately for each year and
validated on the held-out aerial-photography sample, and the final maps
were post-processed with a majority filter to suppress salt-and-pepper
noise. The class definitions follow the municipal ordinance, so that the
output can be used directly in regulatory workflows.

\section{Results}
Figure~\ref{fig:classification-map} presents the 2024 map.
\begin{figure}[t]
\centering
\IfFileExists{figures/classification_map.pdf}{\includegraphics[width=0.85\columnwidth]{figures/classification_map.pdf}}{\rule{0.85\columnwidth}{3.6cm}}
\caption{Map.}
\label{fig:classification-map}
\end{figure}

The per-class definitions and their mapped areas are given in
Table~\ref{tab:classes}.
\begin{table}[t]
\centering
\caption{Classes.}
\label{tab:classes}
\begin{tabular}{lr}
\toprule
Class & Area (ha) \\
\midrule
Tree canopy & 2{,}910 \\
Lawn and meadow & 1{,}740 \\
Allotment gardens & 620 \\
Water bodies & 310 \\
\bottomrule
\end{tabular}
\end{table}

Accuracy against the held-out validation sample is summarised in
Table~\ref{tab:accuracy}.
\begin{table}[t]
\centering
\caption{Accuracy.}
\label{tab:accuracy}
\begin{tabular}{lcc}
\toprule
Class & User's (\%) & Producer's (\%) \\
\midrule
Tree canopy & 94.8 & 93.5 \\
Lawn and meadow & 90.2 & 91.7 \\
Allotment gardens & 86.4 & 83.1 \\
\bottomrule
\end{tabular}
\end{table}

The seasonal behaviour of the mapped classes is shown in
Figure~\ref{fig:seasonal}.
\begin{figure}[t]
\centering
\IfFileExists{figures/seasonal_profiles.pdf}{\includegraphics[width=0.85\columnwidth]{figures/seasonal_profiles.pdf}}{\rule{0.85\columnwidth}{3.4cm}}
\caption{Results.}
\label{fig:seasonal}
\end{figure}

Change detection between 2019 and 2024 reveals a net gain of 4.7\% in
green cover, concentrated in the former industrial districts where
brownfield redevelopment added parkland, and a small net loss of street
trees in the historic core. Figure~\ref{fig:validation} compares the
mapped change against the municipal permit records.
\begin{figure}[t]
\centering
\IfFileExists{figures/validation_scatter.pdf}{\includegraphics[width=0.8\columnwidth]{figures/validation_scatter.pdf}}{\rule{0.8\columnwidth}{3.4cm}}
\caption{Comparison.}
\label{fig:validation}
\end{figure}

\section{Discussion}
The pipeline achieves an overall accuracy of 93.1\%, which is sufficient
for the regulatory use cases that motivated the work, and the
year-to-year stability of the maps is high enough that the detected
4.7\% gain is more than three times the estimated change-detection
noise floor. The allotment class remains the weakest, as expected from
its spectral similarity to intensively managed lawn, and its
misclassifications account for most of the residual error.

The main limitations are the 10~m resolution, which merges small
courtyards and tree rows into their surroundings, and the reliance on
the municipal polygons for training, which imports any systematic bias
of the inventory into the classifier. The aerial-photography validation
mitigates the second concern for accuracy assessment but not for
training.

\section{Conclusion}
Monthly Sentinel-2 composites with a phenology-aware classifier can
reproduce and update a municipal green-space inventory at negligible
marginal cost, and the six-year record already reveals change at a
scale that matters for urban policy. The pipeline is being transferred
to the city administration, and the released code and validation sample
are intended to lower the barrier for other mid-sized cities facing the
same inventory problem.
\end{document}
